mapper.select:
select av.achievement_id as "sourceAchievementId", dcc.evaluation_year as "evaluationYear", dcc.area_code as "areaCode", dcc.department_organization_code as "organizationCode", av.handler_user_id as "targetUserId", av.next_status as "sourceStatus", 'READY' as "generationStatus", null as "generationBatchId", av.processed_at as "lastProcessedAt", null as "excludedReason" from achievement_verifications av join department_chair_confirmations dcc on dcc.achievement_id = av.achievement_id where dcc.evaluation_year = #{request.evaluationYear} and dcc.area_code = #{request.areaCode}
and dcc.department_organization_code = #{request.organizationCode}
and av.handler_user_id = #{request.targetUserId}
order by av.achievement_id

select count(*)
from evaluation_materials
where source_achievement_id = #{sourceAchievementId}
  and evaluation_year = #{evaluationYear}
  and area_code = #{areaCode}
  and target_user_id = #{targetUserId}
  and deleted_yn = 'N'

mapper.insert:
insert into evaluation_materials (evaluation_year, area_code, organization_code, target_user_id,
    source_achievement_id, source_status, generation_batch_id, material_status, base_score, calculated_score,
    score_basis_ref, deleted_yn, request_id, created_by, updated_by)
select #{candidate.evaluationYear}, #{candidate.areaCode}, #{candidate.organizationCode}, #{candidate.targetUserId},
       #{candidate.sourceAchievementId}, #{candidate.sourceStatus}, #{batchJobId}, 'CERTIFIED', 0, 0,
       concat('B46-GENERATION:', #{batchJobId}, ':', #{candidate.sourceAchievementId}), 'N', #{requestId}, #{createdBy}, #{createdBy}
where not exists (
    select 1 from evaluation_materials existing
    where existing.source_achievement_id = #{candidate.sourceAchievementId}
      and existing.evaluation_year = #{candidate.evaluationYear}
      and existing.area_code = #{candidate.areaCode}
      and existing.target_user_id = #{candidate.targetUserId}
      and existing.deleted_yn = 'N'
)
